const cssInject = (fileName) => {
  const link = document.createElement('link');
  link.rel = 'stylesheet';
  link.href = fileName;
  document.head.appendChild(link);
  return new Promise((resolve, reject) => {
    link.onload = resolve;
    link.onerror = reject;
  });
}
MUSE_GLOBAL.waitFor(cssInject(new URL("assets/index-BeGfgbtf.css",import.meta.url)));

